CREATE TABLE workers (id TEXT PRIMARY KEY, name TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, access_role TEXT NOT NULL, can_manage_schedule_engine INTEGER NOT NULL DEFAULT 0);
CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, task_sort_order INTEGER NOT NULL, task_name TEXT NOT NULL, task_group_id TEXT, baseline_start_date TEXT, baseline_end_date TEXT, start_date TEXT, end_date TEXT, primary_worker_id TEXT);
CREATE TABLE task_assignees (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, worker_id TEXT NOT NULL, assignment_role TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE temporary_primary_assignments (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, temporary_primary_employee_id TEXT NOT NULL, effective_start_date TEXT NOT NULL, effective_end_date TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE task_dependencies (dependency_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, predecessor_task_id TEXT NOT NULL, successor_task_id TEXT NOT NULL, dependency_type TEXT NOT NULL DEFAULT 'FINISH_TO_START', lag_work_minutes INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'PROPOSED', confidence_score INTEGER NOT NULL DEFAULT 100, confidence_level TEXT NOT NULL DEFAULT 'HIGH', proposal_source TEXT NOT NULL DEFAULT 'TEST', proposal_evidence_json TEXT NOT NULL DEFAULT '[]', proposed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, proposed_by TEXT NOT NULL, confirmed_at TEXT, confirmed_by TEXT, rejected_at TEXT, rejected_by TEXT, rejection_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shadow_engine_audit_events (audit_id TEXT PRIMARY KEY, event_type TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, actor_employee_id TEXT, actor_mode TEXT NOT NULL, event_time_utc TEXT NOT NULL, before_json TEXT, after_json TEXT, reason TEXT, test_session_id TEXT, request_id TEXT);
CREATE TABLE shadow_engine_idempotency_keys (idempotency_key TEXT PRIMARY KEY, operation TEXT NOT NULL, payload_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dependency_graph_guard (guard_id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 0, lock_token TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
